package narrative
import (
 "testing"
 "corerp.local/backend/internal/core"
)
func TestDiagnosticExpressionTargetRequiresObservableEvidence(t *testing.T) {
 in:=core.RPNarrativeInput{ControlledEntityID:"player",Style:core.RPStyleProfile{POV:"second_person"},Facts:[]core.RPNarrativeFact{
  {EventID:"player-speech",ActorID:"player",ActorName:"你",Action:"speak"},
  {EventID:"npc-nod",ActorID:"baochai",ActorName:"宝钗",Action:"expression",ExpressionCode:"nod"},
  {EventID:"other-npc",ActorID:"xiren",ActorName:"袭人",Action:"silence"},
 }}
 if err:=validateProseSceneClaims("宝钗点头。",in);err!=nil {t.Fatal("sourced undirected nod should remain valid",err)}
 for _,draft:=range []string{"宝钗对你点头。","宝钗向你点了点头。","宝钗向袭人点头。"} {
  t.Run(draft,func(t *testing.T){if err:=validateProseSceneClaims(draft,in);err==nil{t.Fatal("Narrator invented a gesture target without target evidence")}})
 }
}
